//! MCP server configuration.//!//! Stores configuration for connecting to hosted MCP servers.//! Configuration is persisted at ~/.ironclaw/mcp-servers.json.use std::collections::HashMap;use std::path::{Path, PathBuf};use serde::{Deserialize, Serialize};use tokio::fs;use crate::bootstrap::ironclaw_base_dir;use crate::tools::tool::ToolError;/// Transport configuration for an MCP server.#[derive(Debug, Clone, Serialize, Deserialize)]#[serde(tag = "transport", rename_all = "lowercase")]pub enum McpTransportConfig {    /// HTTP/HTTPS transport (uses the `url` field on McpServerConfig).    Http,    /// Stdio transport — spawns a child process.    Stdio {        command: String,        #[serde(default)]        args: Vec<String>,        #[serde(default)]        env: HashMap<String, String>,    },    /// Unix domain socket transport.    Unix { socket_path: String },}/// Configuration for connecting to a remote MCP server.#[derive(Debug, Clone, Serialize, Deserialize)]pub struct McpServerConfig {    /// Unique name for this server (e.g., "notion", "github").    pub name: String,    /// Server URL (must be HTTPS for remote servers).    pub url: String,    /// Transport configuration. If `None`, defaults to Http using `url`.    #[serde(default, skip_serializing_if = "Option::is_none")]    pub transport: Option<McpTransportConfig>,    /// Custom headers to include in every HTTP request.    #[serde(default, skip_serializing_if = "HashMap::is_empty")]    pub headers: HashMap<String, String>,    /// OAuth configuration (if server requires authentication).    #[serde(skip_serializing_if = "Option::is_none")]    pub oauth: Option<OAuthConfig>,    /// Whether this server is enabled.    #[serde(default = "default_true")]    pub enabled: bool,    /// Optional description for the server.    #[serde(skip_serializing_if = "Option::is_none")]    pub description: Option<String>,}fn default_true() -> bool {    true}impl McpServerConfig {    /// Create a new MCP server configuration.    pub fn new(name: impl Into<String>, url: impl Into<String>) -> Self {        Self {            name: name.into(),            url: url.into(),            transport: None,            headers: HashMap::new(),            oauth: None,            enabled: true,            description: None,        }    }    /// Create a new stdio transport MCP server configuration.    pub fn new_stdio(        name: impl Into<String>,        command: impl Into<String>,        args: Vec<String>,        env: HashMap<String, String>,    ) -> Self {        Self {            name: name.into(),            url: String::new(),            transport: Some(McpTransportConfig::Stdio {                command: command.into(),                args,                env,            }),            headers: HashMap::new(),            oauth: None,            enabled: true,            description: None,        }    }    /// Create a new Unix socket transport MCP server configuration.    pub fn new_unix(name: impl Into<String>, socket_path: impl Into<String>) -> Self {        Self {            name: name.into(),            url: String::new(),            transport: Some(McpTransportConfig::Unix {                socket_path: socket_path.into(),            }),            headers: HashMap::new(),            oauth: None,            enabled: true,            description: None,        }    }    /// Set OAuth configuration.    pub fn with_oauth(mut self, oauth: OAuthConfig) -> Self {        self.oauth = Some(oauth);        self    }    /// Set description.    pub fn with_description(mut self, description: impl Into<String>) -> Self {        self.description = Some(description.into());        self    }    /// Set custom headers.    pub fn with_headers(mut self, headers: HashMap<String, String>) -> Self {        self.headers = headers;        self    }    /// Get the effective transport type.    pub fn effective_transport(&self) -> EffectiveTransport<'_> {        match &self.transport {            Some(McpTransportConfig::Http) | None => EffectiveTransport::Http,            Some(McpTransportConfig::Stdio { command, args, env }) => {                EffectiveTransport::Stdio { command, args, env }            }            Some(McpTransportConfig::Unix { socket_path }) => {                EffectiveTransport::Unix { socket_path }            }        }    }    /// Validate the server configuration.    pub fn validate(&self) -> Result<(), ConfigError> {        if self.name.is_empty() {            return Err(ConfigError::InvalidConfig {                reason: "Server name cannot be empty".to_string(),            });        }        match self.effective_transport() {            EffectiveTransport::Http => {                if self.url.is_empty() {                    return Err(ConfigError::InvalidConfig {                        reason: "Server URL cannot be empty".to_string(),                    });                }                // Remote servers must use HTTPS (localhost is allowed for development)                let is_localhost = is_localhost_url(&self.url);                if !is_localhost && !self.url.to_lowercase().starts_with("https://") {                    return Err(ConfigError::InvalidConfig {                        reason: "Remote MCP servers must use HTTPS".to_string(),                    });                }            }            EffectiveTransport::Stdio { command, .. } => {                if command.is_empty() {                    return Err(ConfigError::InvalidConfig {                        reason: "Stdio transport command cannot be empty".to_string(),                    });                }            }            EffectiveTransport::Unix { socket_path } => {                if socket_path.is_empty() {                    return Err(ConfigError::InvalidConfig {                        reason: "Unix socket path cannot be empty".to_string(),                    });                }            }        }        // Validate custom header names and values using the http crate's RFC 9110        // token validation (catches CRLF, spaces, colons, null bytes, etc.)        for (name, value) in &self.headers {            if name.is_empty() {                return Err(ConfigError::InvalidConfig {                    reason: "Header name cannot be empty".to_string(),                });            }            if reqwest::header::HeaderName::from_bytes(name.as_bytes()).is_err() {                return Err(ConfigError::InvalidConfig {                    reason: format!(                        "Header name '{}' is not a valid HTTP header name (RFC 9110)",                        name                    ),                });            }            if reqwest::header::HeaderValue::from_str(value).is_err() {                return Err(ConfigError::InvalidConfig {                    reason: format!("Header value for '{}' contains invalid characters", name),                });            }        }        Ok(())    }    /// Check if any custom header sets an Authorization value.    ///    /// Used to skip OAuth token injection when the user has explicitly    /// configured an Authorization header (e.g. for API-key-based servers).    pub fn has_custom_auth_header(&self) -> bool {        self.headers            .keys()            .any(|k| k.eq_ignore_ascii_case("authorization"))    }    /// Check if this server requires authentication.    ///    /// Returns true if OAuth is pre-configured OR if this is a remote HTTPS server    /// (which likely supports Dynamic Client Registration even without pre-configured OAuth).    ///    /// Non-HTTP transports (stdio, unix) never require auth.    pub fn requires_auth(&self) -> bool {        // Non-HTTP transports don't use HTTP auth        if !matches!(self.effective_transport(), EffectiveTransport::Http) {            return false;        }        if self.oauth.is_some() {            return true;        }        // Remote HTTPS servers need auth handling (DCR, token refresh, 401 detection).        // Localhost/127.0.0.1 servers are assumed to be dev servers without auth.        let url_lower = self.url.to_lowercase();        let is_localhost = is_localhost_url(&url_lower);        url_lower.starts_with("https://") && !is_localhost    }    /// Get the secret name used to store the access token.    pub fn token_secret_name(&self) -> String {        format!("mcp_{}_access_token", self.name)    }    /// Get the secret name used to store the refresh token.    pub fn refresh_token_secret_name(&self) -> String {        format!("mcp_{}_refresh_token", self.name)    }    /// Get the secret name used to store the DCR client ID.    pub fn client_id_secret_name(&self) -> String {        format!("mcp_{}_client_id", self.name)    }}/// OAuth 2.1 configuration for an MCP server.#[derive(Debug, Clone, Serialize, Deserialize)]pub struct OAuthConfig {    /// OAuth client ID.    pub client_id: String,    /// Authorization endpoint URL.    /// If not provided, will be discovered from /.well-known/oauth-protected-resource.    #[serde(skip_serializing_if = "Option::is_none")]    pub authorization_url: Option<String>,    /// Token endpoint URL.    /// If not provided, will be discovered from /.well-known/oauth-authorization-server.    #[serde(skip_serializing_if = "Option::is_none")]    pub token_url: Option<String>,    /// Scopes to request.    #[serde(default)]    pub scopes: Vec<String>,    /// Whether to use PKCE (default: true, as required by OAuth 2.1).    #[serde(default = "default_true")]    pub use_pkce: bool,    /// Extra parameters to include in the authorization request.    #[serde(default)]    pub extra_params: HashMap<String, String>,}impl OAuthConfig {    /// Create a new OAuth configuration with just a client ID.    pub fn new(client_id: impl Into<String>) -> Self {        Self {            client_id: client_id.into(),            authorization_url: None,            token_url: None,            scopes: Vec::new(),            use_pkce: true,            extra_params: HashMap::new(),        }    }    /// Set authorization and token URLs.    pub fn with_endpoints(        mut self,        authorization_url: impl Into<String>,        token_url: impl Into<String>,    ) -> Self {        self.authorization_url = Some(authorization_url.into());        self.token_url = Some(token_url.into());        self    }    /// Set scopes.    pub fn with_scopes(mut self, scopes: Vec<String>) -> Self {        self.scopes = scopes;        self    }}/// Configuration file containing all MCP servers.#[derive(Debug, Clone, Default, Serialize, Deserialize)]pub struct McpServersFile {    /// List of configured MCP servers.    #[serde(default)]    pub servers: Vec<McpServerConfig>,    /// Schema version for future compatibility.    #[serde(default = "default_schema_version")]    pub schema_version: u32,}fn default_schema_version() -> u32 {    1}impl McpServersFile {    /// Get a server by name.    pub fn get(&self, name: &str) -> Option<&McpServerConfig> {        self.servers.iter().find(|s| s.name == name)    }    /// Get a mutable server by name.    pub fn get_mut(&mut self, name: &str) -> Option<&mut McpServerConfig> {        self.servers.iter_mut().find(|s| s.name == name)    }    /// Add or update a server configuration.    pub fn upsert(&mut self, config: McpServerConfig) {        if let Some(existing) = self.get_mut(&config.name) {            *existing = config;        } else {            self.servers.push(config);        }    }    /// Remove a server by name.    pub fn remove(&mut self, name: &str) -> bool {        let len_before = self.servers.len();        self.servers.retain(|s| s.name != name);        self.servers.len() < len_before    }    /// Get all enabled servers.    pub fn enabled_servers(&self) -> impl Iterator<Item = &McpServerConfig> {        self.servers.iter().filter(|s| s.enabled)    }}/// Error type for MCP configuration operations.#[derive(Debug, thiserror::Error)]pub enum ConfigError {    #[error("IO error: {0}")]    Io(#[from] std::io::Error),    #[error("JSON error: {0}")]    Json(#[from] serde_json::Error),    #[error("Invalid configuration: {reason}")]    InvalidConfig { reason: String },    #[error("Server not found: {name}")]    ServerNotFound { name: String },}impl From<ConfigError> for ToolError {    fn from(err: ConfigError) -> Self {        ToolError::ExternalService(err.to_string())    }}/// Get the default MCP servers configuration path.pub fn default_config_path() -> PathBuf {    ironclaw_base_dir().join("mcp-servers.json")}/// Load MCP server configurations from the default location.pub async fn load_mcp_servers() -> Result<McpServersFile, ConfigError> {    load_mcp_servers_from(default_config_path()).await}/// Load MCP server configurations from a specific path.pub async fn load_mcp_servers_from(path: impl AsRef<Path>) -> Result<McpServersFile, ConfigError> {    let path = path.as_ref();    if !path.exists() {        return Ok(McpServersFile::default());    }    let content = fs::read_to_string(path).await?;    let config: McpServersFile = serde_json::from_str(&content)?;    // Validate every server on load so corrupted configs are caught early    for server in &config.servers {        server.validate().map_err(|e| ConfigError::InvalidConfig {            reason: format!("Server '{}': {}", server.name, e),        })?;    }    Ok(config)}/// Save MCP server configurations to the default location.pub async fn save_mcp_servers(config: &McpServersFile) -> Result<(), ConfigError> {    save_mcp_servers_to(config, default_config_path()).await}/// Save MCP server configurations to a specific path.